# nginx has no built-in lower-casing; with the perl module (http block):
perl_set $uri_lowercase 'sub { my $r = shift; return lc($r->uri); }';

# server block
location ~ [A-Z] {
    return 301 $scheme://$host$uri_lowercase$is_args$args;
}

