{
  "protocolVersion": "0.3.0",
  "name": "Harbourline booking assistant",
  "description": "Answers questions about Harbourline Dental Studio treatments and requests appointments.",
  "url": "http://127.0.0.1:38107/a2a",
  "preferredTransport": "JSONRPC",
  "provider": {
    "organization": "Harbourline Dental Studio",
    "url": "http://127.0.0.1:38107/"
  },
  "capabilities": {
    "streaming": false,
    "pushNotifications": false
  },
  "defaultInputModes": [
    "text/plain"
  ],
  "defaultOutputModes": [
    "text/plain"
  ]
}

{
  "issuer": "https://auth.harbourline-dental.example",
  "authorization_endpoint": "http://127.0.0.1:38107/oauth/authorize",
  "token_endpoint": "http://127.0.0.1:38107/oauth/token",
  "response_types_supported": [
    "code"
  ],
  "grant_types_supported": [
    "authorization_code",
    "refresh_token"
  ],
  "code_challenge_methods_supported": [
    "S256"
  ],
  "token_endpoint_auth_methods_supported": [
    "none"
  ],
  "scopes_supported": [
    "availability:read"
  ]
}

